solution.code:
def biaya_layanan(p):
    keluar = max(0, p['keluar_gb'] - GRATIS_KELUAR_GB)
    total = p['vm_jam'] * HARGA['vm_jam'] + p['disk_gb'] * HARGA['disk_gb'] + keluar * HARGA['keluar_gb']
    return round(total, 2)


def total_per_tag(daftar):
    hasil = {}
    for p in daftar:
        hasil[p['tag']] = hasil.get(p['tag'], 0) + biaya_layanan(p)
    return {t: round(v, 2) for t, v in hasil.items()}


def layanan_termahal(daftar):
    return max(daftar, key=biaya_layanan)['layanan']


def terlalu_mahal(daftar, anggaran):
    return [p['layanan'] for p in daftar if biaya_layanan(p) > anggaran]

