from fnmatch import fnmatchcase


def izinkan(kebijakan, aksi, sumber):
    cocok = [k for k in kebijakan if fnmatchcase(aksi, k['aksi']) and fnmatchcase(sumber, k['sumber'])]
    if any(k['efek'] == 'deny' for k in cocok):
        return False
    return any(k['efek'] == 'allow' for k in cocok)

